// The real bin colours (design/tokens.md), the one place they are set: the
// site's --waste-* custom properties (app/waste-colours.css, generated by
// scripts/brand-assets.ts, not in git), the PDF's marks and the contrast
// check read them. A -border is the outline that carries the non-text
// contrast of a light fill; -print is the PDF's, darker for small marks on
// paper.
export const WASTE_COLOURS: Record<string, string> = {
  zmieszane: "#111111",
  "zmieszane-border": "#111111",
  papier: "#1f63c7",
  "plastik-metale": "#f2c200",
  "plastik-metale-border": "#7d6200",
  "plastik-metale-print": "#5c4800",
  szklo: "#1e7f4f",
  bio: "#7a4b2a",
  popiol: "#5c6370",
  gabaryty: "#c2410c",
  elektro: "#1e3a8a",
  "elektro-border": "transparent",
  opony: "#a3aab5",
  "opony-border": "#4a5160",
  tekstylia: "#a8336a",
};

/** The colours above as CSS custom properties, for app/waste-colours.css. */
export function wasteColoursCss(): string {
  const lines = Object.entries(WASTE_COLOURS).map(
    ([name, value]) => `  --waste-${name}: ${value};`,
  );
  return [
    "/* Generated from lib/waste-colours.ts by scripts/brand-assets.ts; not in",
    "   git, do not edit. */",
    ":root {",
    ...lines,
    "}",
    "",
  ].join("\n");
}
